// ===== Layout verification (offsets computed by scripts/gen.ts vs the C compiler) =====

_Static_assert(sizeof(Vector2) == 8, "size_Vector2");
_Static_assert(offsetof(Vector2, x) == 0, "off_Vector2_x");
_Static_assert(offsetof(Vector2, y) == 4, "off_Vector2_y");
_Static_assert(sizeof(Vector3) == 12, "size_Vector3");
_Static_assert(offsetof(Vector3, x) == 0, "off_Vector3_x");
_Static_assert(offsetof(Vector3, y) == 4, "off_Vector3_y");
_Static_assert(offsetof(Vector3, z) == 8, "off_Vector3_z");
_Static_assert(sizeof(Vector4) == 16, "size_Vector4");
_Static_assert(offsetof(Vector4, x) == 0, "off_Vector4_x");
_Static_assert(offsetof(Vector4, y) == 4, "off_Vector4_y");
_Static_assert(offsetof(Vector4, z) == 8, "off_Vector4_z");
_Static_assert(offsetof(Vector4, w) == 12, "off_Vector4_w");
_Static_assert(sizeof(Matrix) == 64, "size_Matrix");
_Static_assert(offsetof(Matrix, m0) == 0, "off_Matrix_m0");
_Static_assert(offsetof(Matrix, m4) == 4, "off_Matrix_m4");
_Static_assert(offsetof(Matrix, m8) == 8, "off_Matrix_m8");
_Static_assert(offsetof(Matrix, m12) == 12, "off_Matrix_m12");
_Static_assert(offsetof(Matrix, m1) == 16, "off_Matrix_m1");
_Static_assert(offsetof(Matrix, m5) == 20, "off_Matrix_m5");
_Static_assert(offsetof(Matrix, m9) == 24, "off_Matrix_m9");
_Static_assert(offsetof(Matrix, m13) == 28, "off_Matrix_m13");
_Static_assert(offsetof(Matrix, m2) == 32, "off_Matrix_m2");
_Static_assert(offsetof(Matrix, m6) == 36, "off_Matrix_m6");
_Static_assert(offsetof(Matrix, m10) == 40, "off_Matrix_m10");
_Static_assert(offsetof(Matrix, m14) == 44, "off_Matrix_m14");
_Static_assert(offsetof(Matrix, m3) == 48, "off_Matrix_m3");
_Static_assert(offsetof(Matrix, m7) == 52, "off_Matrix_m7");
_Static_assert(offsetof(Matrix, m11) == 56, "off_Matrix_m11");
_Static_assert(offsetof(Matrix, m15) == 60, "off_Matrix_m15");
_Static_assert(sizeof(Color) == 4, "size_Color");
_Static_assert(offsetof(Color, r) == 0, "off_Color_r");
_Static_assert(offsetof(Color, g) == 1, "off_Color_g");
_Static_assert(offsetof(Color, b) == 2, "off_Color_b");
_Static_assert(offsetof(Color, a) == 3, "off_Color_a");
_Static_assert(sizeof(Rectangle) == 16, "size_Rectangle");
_Static_assert(offsetof(Rectangle, x) == 0, "off_Rectangle_x");
_Static_assert(offsetof(Rectangle, y) == 4, "off_Rectangle_y");
_Static_assert(offsetof(Rectangle, width) == 8, "off_Rectangle_width");
_Static_assert(offsetof(Rectangle, height) == 12, "off_Rectangle_height");
_Static_assert(sizeof(Image) == 24, "size_Image");
_Static_assert(offsetof(Image, data) == 0, "off_Image_data");
_Static_assert(offsetof(Image, width) == 8, "off_Image_width");
_Static_assert(offsetof(Image, height) == 12, "off_Image_height");
_Static_assert(offsetof(Image, mipmaps) == 16, "off_Image_mipmaps");
_Static_assert(offsetof(Image, format) == 20, "off_Image_format");
_Static_assert(sizeof(Texture) == 20, "size_Texture");
_Static_assert(offsetof(Texture, id) == 0, "off_Texture_id");
_Static_assert(offsetof(Texture, width) == 4, "off_Texture_width");
_Static_assert(offsetof(Texture, height) == 8, "off_Texture_height");
_Static_assert(offsetof(Texture, mipmaps) == 12, "off_Texture_mipmaps");
